import type { Quat, Vec3 } from '../contracts/math';
import { requireFinite, requirePositive, requireVec3 } from './validation';

export const TAU = Math.PI * 2;

export function wrapAngle(angle: number): number {
  if (!Number.isFinite(angle)) return 0;
  const wrapped = angle % TAU;
  return wrapped < 0 ? wrapped + TAU : wrapped;
}

export function normalizeAxis(axis: Vec3): Vec3 {
  requireVec3(axis, 'rotation axis');
  const length = Math.hypot(axis.x, axis.y, axis.z);
  if (length <= Number.EPSILON) throw new Error('rotation axis must have non-zero length');
  return { x: axis.x / length, y: axis.y / length, z: axis.z / length };
}

export function quaternionFromAxisAngle(axis: Vec3, angle: number): Quat {
  const unit = normalizeAxis(axis);
  const half = angle * 0.5;
  const sin = Math.sin(half);
  return { x: unit.x * sin, y: unit.y * sin, z: unit.z * sin, w: Math.cos(half) };
}

export function rotateVector(rotation: Quat, vector: Vec3): Vec3 {
  const { x: qx, y: qy, z: qz, w: qw } = rotation;
  const tx = 2 * (qy * vector.z - qz * vector.y);
  const ty = 2 * (qz * vector.x - qx * vector.z);
  const tz = 2 * (qx * vector.y - qy * vector.x);
  return {
    x: vector.x + qw * tx + (qy * tz - qz * ty),
    y: vector.y + qw * ty + (qz * tx - qx * tz),
    z: vector.z + qw * tz + (qx * ty - qy * tx),
  };
}

export interface RotationDriverOptions {
  speed: number;
  phase?: number;
  maxStepSeconds?: number;
}

export class RotationDriver {
  readonly speed: number;
  readonly phase: number;
  readonly maxStepSeconds: number;
  private elapsedSeconds = 0;

  constructor(options: RotationDriverOptions) {
    this.speed = requireFinite(options.speed, 'rotation speed');
    this.phase = requireFinite(options.phase ?? 0, 'rotation phase');
    this.maxStepSeconds = requirePositive(options.maxStepSeconds ?? 0.1, 'max rotation step');
  }

  get elapsed(): number { return this.elapsedSeconds; }
  get angle(): number { return wrapAngle(this.phase + this.speed * this.elapsedSeconds); }

  advance(deltaSeconds: number): number {
    if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return this.angle;
    this.elapsedSeconds += Math.min(deltaSeconds, this.maxStepSeconds);
    return this.angle;
  }

  setElapsed(seconds: number): number {
    this.elapsedSeconds = Math.max(0, requireFinite(seconds, 'elapsed rotation time'));
    return this.angle;
  }

  reset(): number {
    this.elapsedSeconds = 0;
    return this.angle;
  }
}
EOF

